-- =============================================================================
-- Ankit Stationery Mart — schema for Supabase / PostgreSQL
--
-- The FastAPI backend owns all writes (it connects with the service role and
-- bypasses RLS). This migration mirrors the SQLAlchemy models exactly so the
-- same application code can run against SQLite locally and Postgres in the
-- cloud, and adds the constraints that make payment/stock bugs impossible.
--
-- Identifiers are `text` (36-char UUIDs generated by the app or by
-- gen_random_uuid()::text) to stay byte-compatible with the ORM.
-- All money columns are integer paise. All timestamps are UTC.
-- =============================================================================

create extension if not exists "pgcrypto";

-- -----------------------------------------------------------------------------
-- identity
-- -----------------------------------------------------------------------------
create table if not exists profiles (
  id            text primary key,
  email         text not null unique,
  full_name     text not null default '',
  phone         text,
  role          text not null default 'customer' check (role in ('customer', 'staff', 'admin')),
  avatar_url    text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  last_login_at timestamptz
);

create table if not exists addresses (
  id           text primary key,
  user_id      text not null references profiles (id) on delete cascade,
  label        text not null default 'Home',
  contact_name text not null,
  phone        text not null,
  line1        text not null,
  line2        text,
  locality     text,
  city         text not null default 'Shimla',
  state        text not null default 'Himachal Pradesh',
  pincode      text not null,
  is_default   boolean not null default false,
  created_at   timestamptz not null default now()
);
create index if not exists ix_addresses_user on addresses (user_id);

-- -----------------------------------------------------------------------------
-- catalogue
-- -----------------------------------------------------------------------------
create table if not exists categories (
  id          text primary key,
  name        text not null unique,
  slug        text not null unique,
  description text,
  image_url   text,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now()
);

create table if not exists products (
  id            text primary key,
  sku           text not null unique,
  slug          text not null unique,
  name          text not null,
  description   text not null default '',
  category_id   text references categories (id) on delete set null,
  price_paise   integer not null check (price_paise > 0),
  mrp_paise     integer check (mrp_paise is null or mrp_paise >= 0),
  stock         integer not null default 0 check (stock >= 0),
  unit          text not null default 'each',
  brand         text,
  isbn          text,
  author        text,
  class_level   text,
  board         text,
  condition     text not null default 'new' check (condition in ('new', 'refurbished', 'used')),
  tags          text not null default '',
  image_url     text,
  is_featured   boolean not null default false,
  is_archived   boolean not null default false,
  sold_count    integer not null default 0 check (sold_count >= 0),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists ix_products_catalog on products (is_archived, category_id, price_paise);
create index if not exists ix_products_name on products (name);
create index if not exists ix_products_isbn on products (isbn);

create table if not exists coupons (
  id                  text primary key,
  code                text not null unique,
  kind                text not null default 'percent' check (kind in ('percent', 'flat')),
  value               integer not null check (value > 0),
  min_subtotal_paise  integer not null default 0,
  max_discount_paise  integer,
  active              boolean not null default true,
  used_count          integer not null default 0,
  created_at          timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- orders
-- -----------------------------------------------------------------------------
create table if not exists orders (
  id               text primary key,
  order_number     text not null unique,
  user_id          text not null references profiles (id),
  status           text not null default 'payment_pending'
                   check (status in ('payment_pending', 'payment_failed', 'confirmed', 'processing',
                                     'packed', 'shipped', 'out_for_delivery', 'delivered',
                                     'cancelled', 'refunded')),
  payment_method   text not null default 'razorpay' check (payment_method in ('razorpay', 'cod', 'pickup')),
  payment_status   text not null default 'unpaid'
                   check (payment_status in ('unpaid', 'pending', 'paid', 'failed', 'refund_due', 'refunded')),
  contact_name     text not null,
  phone            text not null,
  email            text not null default '',
  line1            text not null,
  line2            text,
  locality         text,
  city             text not null,
  state            text not null,
  pincode          text not null,
  notes            text,
  subtotal_paise   integer not null check (subtotal_paise >= 0),
  shipping_paise   integer not null default 0 check (shipping_paise >= 0),
  discount_paise   integer not null default 0 check (discount_paise >= 0),
  total_paise      integer not null check (total_paise >= 0),
  coupon_code      text,
  courier          text,
  tracking_number  text,
  cancel_reason    text,
  stock_released   boolean not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  paid_at          timestamptz,
  delivered_at     timestamptz,
  constraint orders_total_matches_parts
    check (total_paise = subtotal_paise - discount_paise + shipping_paise),
  constraint orders_paid_has_timestamp
    check (payment_status <> 'paid' or paid_at is not null)
);
create index if not exists ix_orders_user on orders (user_id);
create index if not exists ix_orders_status on orders (status);
create index if not exists ix_orders_created on orders (created_at desc);

create table if not exists order_items (
  id               text primary key,
  order_id         text not null references orders (id) on delete cascade,
  product_id       text references products (id) on delete set null,
  sku              text not null,
  name             text not null,
  image_url        text,
  unit_price_paise integer not null check (unit_price_paise > 0),
  quantity         integer not null check (quantity > 0),
  line_total_paise integer not null check (line_total_paise = unit_price_paise * quantity),
  created_at       timestamptz not null default now()
);
create index if not exists ix_order_items_order on order_items (order_id);

create table if not exists order_status_events (
  id         text primary key,
  order_id   text not null references orders (id) on delete cascade,
  status     text not null,
  note       text,
  actor_id   text,
  created_at timestamptz not null default now()
);
create index if not exists ix_order_status_events_order on order_status_events (order_id);

create table if not exists payments (
  id                  text primary key,
  order_id            text not null references orders (id) on delete cascade,
  provider            text not null default 'razorpay',
  provider_order_id   text,
  provider_payment_id text unique,
  amount_paise        integer not null check (amount_paise >= 0),
  status              text not null default 'created',
  method              text,
  signature_verified  boolean not null default false,
  failure_reason      text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index if not exists ix_payments_order on payments (order_id);
create index if not exists ix_payments_provider_order on payments (provider_order_id);

-- Every provider event lands here exactly once; the unique event_id is what
-- makes webhook delivery idempotent (duplicate inserts are rejected).
create table if not exists payment_events (
  id          text primary key,
  provider    text not null default 'razorpay',
  event_id    text not null unique,
  event_type  text not null,
  payload     jsonb not null default '{}'::jsonb,
  processed   boolean not null default false,
  note        text,
  created_at  timestamptz not null default now()
);

create table if not exists inventory_movements (
  id         text primary key,
  product_id text not null references products (id) on delete cascade,
  delta      integer not null,
  reason     text not null,
  order_id   text,
  actor_id   text,
  note       text,
  created_at timestamptz not null default now()
);
create index if not exists ix_inventory_movements_product on inventory_movements (product_id);

create table if not exists admin_audit_logs (
  id          text primary key,
  actor_id    text,
  actor_email text,
  action      text not null,
  entity_type text not null,
  entity_id   text,
  meta        jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);
create index if not exists ix_admin_audit_logs_created on admin_audit_logs (created_at desc);

-- -----------------------------------------------------------------------------
-- updated_at maintenance
-- -----------------------------------------------------------------------------
create or replace function set_updated_at() returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

do $$
declare
  t text;
begin
  foreach t in array array['profiles', 'products', 'payments', 'orders'] loop
    execute format(
      'drop trigger if exists trg_%s_updated_at on %I;
       create trigger trg_%s_updated_at before update on %I
       for each row execute function set_updated_at();',
      t, t, t, t
    );
  end loop;
end $$;
